package com.msob7y.namida

import android.content.Context
import android.content.Intent
import android.media.MediaScannerConnection
import android.net.Uri
import android.os.Build
import android.provider.DocumentsContract
import java.io.File
import java.io.OutputStream

/**
 * Helpers for modifying files that can't be written directly through the filesystem
 * (ex: SD card on android <= 10), by utilizing SAF (Storage Access Framework) tree grants.

 * Generated by claude code.
 */
public class SafUtils(private val context: Context) {

  companion object {
    const val EXTERNAL_STORAGE_AUTHORITY = "com.android.externalstorage.documents"
    private val emulatedPathRegex = Regex("^/storage/emulated/0/(.+)$")
    private val storagePathRegex = Regex("^/storage/([^/]+)/(.+)$")
  }

  /** Splits an absolute path into (volumeId, relativePath), ex: `/storage/1D2E-3F4G/Music/a.mp3` => `("1D2E-3F4G", "Music/a.mp3")` */
  private fun splitPath(path: String): Pair<String, String>? {
    val emulatedMatch = emulatedPathRegex.find(path)
    if (emulatedMatch != null) return Pair("primary", emulatedMatch.groupValues[1])
    val match = storagePathRegex.find(path) ?: return null
    return Pair(match.groupValues[1], match.groupValues[2])
  }

  /** Builds a writable document uri for [path] using a persisted tree grant, or null if no grant covers it. */
  fun findDocumentUri(path: String): Uri? {
    val (volumeId, relativePath) = splitPath(path) ?: return null
    for (perm in context.contentResolver.persistedUriPermissions) {
      if (!perm.isWritePermission) continue
      val treeUri = perm.uri
      if (treeUri.authority != EXTERNAL_STORAGE_AUTHORITY) continue
      val treeDocId =
          try {
            DocumentsContract.getTreeDocumentId(treeUri)
          } catch (_: Exception) {
            continue
          }
      // -- treeDocId is like "1D2E-3F4G:" for a volume root, or "1D2E-3F4G:Music" for a subfolder
      val separatorIndex = treeDocId.indexOf(':')
      if (separatorIndex < 0) continue
      val treeVolumeId = treeDocId.substring(0, separatorIndex)
      if (!treeVolumeId.equals(volumeId, ignoreCase = true)) continue
      val treeRelativePath = treeDocId.substring(separatorIndex + 1).trimEnd('/')
      if (treeRelativePath.isNotEmpty() &&
          relativePath != treeRelativePath &&
          !relativePath.startsWith("$treeRelativePath/")
      ) {
        continue
      }
      return DocumentsContract.buildDocumentUriUsingTree(treeUri, "$treeVolumeId:$relativePath")
    }
    return null
  }

  fun buildPickerIntent(path: String): Intent {
    val intent = Intent(Intent.ACTION_OPEN_DOCUMENT_TREE)
    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
      val volumeId = splitPath(path)?.first
      if (volumeId != null) {
        val initialUri = DocumentsContract.buildDocumentUri(EXTERNAL_STORAGE_AUTHORITY, "$volumeId:")
        intent.putExtra(DocumentsContract.EXTRA_INITIAL_URI, initialUri)
      }
    }
    return intent
  }

  fun persistPermission(uri: Uri) {
    context.contentResolver.takePersistableUriPermission(
        uri,
        Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION
    )
  }

  // ------- document trees used as library folders, by claude -------

  fun buildTreePickerIntent(): Intent = Intent(Intent.ACTION_OPEN_DOCUMENT_TREE)

  fun persistReadPermission(uri: Uri) {
    context.contentResolver.takePersistableUriPermission(uri, Intent.FLAG_GRANT_READ_URI_PERMISSION)
  }

  fun hasTreeAccess(treeUri: Uri): Boolean {
    for (perm in context.contentResolver.persistedUriPermissions) {
      if (perm.isReadPermission && perm.uri == treeUri) return true
    }
    return false
  }

  /** Every file under [treeUri] as parallel lists, `dirIndices` point into `dirs` (parent document ids). */
  fun listTree(treeUri: Uri): Map<String, Any> {
    val ids = ArrayList<String>()
    val names = ArrayList<String>()
    val sizes = ArrayList<Long>()
    val modified = ArrayList<Long>()
    val dirIndices = ArrayList<Int>()
    val dirs = ArrayList<String>()
    val projection =
        arrayOf(
            DocumentsContract.Document.COLUMN_DOCUMENT_ID,
            DocumentsContract.Document.COLUMN_DISPLAY_NAME,
            DocumentsContract.Document.COLUMN_MIME_TYPE,
            DocumentsContract.Document.COLUMN_SIZE,
            DocumentsContract.Document.COLUMN_LAST_MODIFIED,
        )
    val resolver = context.contentResolver
    val pending = ArrayDeque<String>()
    pending.add(DocumentsContract.getTreeDocumentId(treeUri))
    while (pending.isNotEmpty()) {
      val parentId = pending.removeFirst()
      val childrenUri = DocumentsContract.buildChildDocumentsUriUsingTree(treeUri, parentId)
      val cursor =
          try {
            resolver.query(childrenUri, projection, null, null, null)
          } catch (_: Exception) {
            null
          } ?: continue
      var dirIndex = -1
      cursor.use {
        while (it.moveToNext()) {
          val id = it.getString(0) ?: continue
          if (it.getString(2) == DocumentsContract.Document.MIME_TYPE_DIR) {
            pending.add(id)
            continue
          }
          if (dirIndex < 0) {
            dirIndex = dirs.size
            dirs.add(parentId)
          }
          ids.add(id)
          names.add(it.getString(1) ?: "")
          sizes.add(if (it.isNull(3)) -1L else it.getLong(3))
          modified.add(if (it.isNull(4)) -1L else it.getLong(4))
          dirIndices.add(dirIndex)
        }
      }
    }
    return mapOf(
        "ids" to ids,
        "names" to names,
        "sizes" to sizes,
        "modified" to modified,
        "dirIndices" to dirIndices,
        "dirs" to dirs,
    )
  }

  /** Returns an error message, or null on success. */
  fun copyDocumentToFile(documentUri: Uri, destPath: String): String? {
    try {
      val input = context.contentResolver.openInputStream(documentUri) ?: return "Failed to open `$documentUri`"
      val dest = File(destPath)
      dest.parentFile?.mkdirs()
      input.use { inp -> dest.outputStream().use { inp.copyTo(it) } }
      return null
    } catch (e: Exception) {
      return e.toString()
    }
  }

  /** Streams [sourcePath] contents over the document backing [destPath]. Returns an error message, or null on success. */
  fun copyFileToDocument(sourcePath: String, destPath: String): String? {
    val destUri = findDocumentUri(destPath) ?: return "No SAF permission covers `$destPath`"
    try {
      val output = openOutputStream(destUri) ?: return "Failed to open output stream for `$destPath`"
      output.use { out -> File(sourcePath).inputStream().use { it.copyTo(out) } }
    } catch (e: Exception) {
      FAudioTagger.writeError(destPath, "copyFileToDocument", "ERROR", e.toString())
      return e.toString()
    }
    try {
      MediaScannerConnection.scanFile(context, arrayOf(destPath), null, null)
    } catch (_: Exception) {}
    return null
  }

  private fun openOutputStream(uri: Uri): OutputStream? {
    // -- "rwt" & "wt" truncate, plain "w" is a last resort that may leave trailing bytes.
    for (mode in arrayOf("rwt", "wt", "w")) {
      try {
        val stream = context.contentResolver.openOutputStream(uri, mode)
        if (stream != null) return stream
      } catch (_: Exception) {}
    }
    return null
  }
}
